import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Tabs, Tab, Input, Link, Card, CardBody, CardHeader, user, Select, SelectItem, RadioGroup, Radio } from "@heroui/react";
import { useFormik } from "formik";

import { ToastContainer, toast } from "react-toastify";
import { useStateContext } from "../../contexts/ContextProvider";
import { DatePicker } from "antd";
import makeAnimated from "react-select/animated"
import CreateSelect from "react-select/creatable";
import moment from 'moment';
import TextInput from "../../components/TextInput";



export default function RoomBookingModal({ showRoomBookingModal, setshowRoomBookingModal, selectedRoomToBook, paymentMethods,countries,newRoomData,setnewRoomData }) {
    const animatedComponent = makeAnimated();
    const [existing, setExisting] = useState()
    const { } = useStateContext()
    // const [selectedRooms, setselectedRooms] = useState(localStorage.getItem("selectedRooms") ? JSON.parse(localStorage.getItem("selectedRooms")) : [])


    const [allGuests, setallGuests] = useState([])
    const [guestsInRoom, setguestsInRoom] = useState(new Array(selectedRoomToBook.occupancy))

    const [selectedPaymentMethod, setselectedPaymentMethod] = useState()
    const [mobileMoneyPhoneRequired, setmobileMoneyPhoneRequired] = useState(false)
    const [mobileMoneyPhone, setmobileMoneyPhone] = useState()
    const [checkinDate, setcheckinDate] = useState()
    const [checkoutDate, setcheckoutDate] = useState()

    const menuItems = []
    const dateFormat = 'YYYY-MM-DD';

    useEffect(() => {


        console.log("All guests", allGuests)

    }, [allGuests])

  


    useEffect(() => {
        if (selectedRoomToBook.occupancy > 0) {
            let stump = null;
            for (let i = 0; i < selectedRoomToBook.occupancy; i++) {
                stump = { "room": selectedRoomToBook.id, "first_name": "", "last_name": "", "gender": "", "identifier_type": "", "identifier_number": "", "age_type": "", "phone": "" }

            }
            setallGuests(prevState => [...prevState, stump])
        }


    }, [selectedRoomToBook.occupancy])

    const identifierTypes = [
        { "label": "National ID", "value": "NationalId" },
        { "label": "Passport", "value": "Passport" },
    ]
    const ageTypes = [
        { "label": "Minor", "value": "Minor" },
        { "label": "Adult", "value": "Adult" },
    ]
    const genderTypes = [
        { "label": "Female", "value": "Female" },
        { "label": "Male", "value": "Male" },
    ]



    const getDays = (from, to) => {

     const days=   Math.abs(
            moment(from, 'YYYY-MM-DD')
                .startOf('day')
                .diff(moment(to, 'YYYY-MM-DD').startOf('day'), 'days')
        )

        return days

    }

    const handleSubmit = (event) => {
        event.preventDefault();
        console.log("eee", event.target.value)
        console.log("allGuests", allGuests)

        const roomData = {
            "id": selectedRoomToBook.id,
            "title": selectedRoomToBook.title,
            "price": selectedRoomToBook.price,
            "checkin_date": checkinDate,
            "checkout_date": checkoutDate,
            "days" :getDays(checkinDate, checkoutDate),
            "totalCost":parseFloat(parseFloat(getDays(checkinDate, checkoutDate) * parseFloat(selectedRoomToBook.price))),
            "guests": allGuests
        }
        console.log("rooomData", roomData)

        setnewRoomData(roomData)
        setshowRoomBookingModal(false)
        //   const data=  {
        //         "action": "CreateBatchedTickets",
        //         "mobile_money_phone": "",
        //         "payment_method": "",
        //         "tickets": allGuests
        //     }

        //     console.log("data",data)

        // createBatchedTickets(data);
    }


    const handleDateInputChange = (index, event) => {
        console.log("Event", event)
        console.log("Index", index)

        const { date, dateArray } = event
        console.log("Index", dateArray)

        // const values = [...allGuests];
        // const updatedValue = event.target.name;
        // values[index][updatedValue] = event.target.value;

        // setallGuests(values);


    };

    // Function to update the value of an input field
    const handleInputChange = (index, event) => {
        console.log("Event", event)
        console.log("Index", index)

        const values = [...allGuests];
        const updatedValue = event.target.name;
        values[index][updatedValue] = event.target.value;

        setallGuests(values);


    };
    const handleCheckinDateChange = (date, dateArray) => {
        console.log("prep", dateArray)
        setcheckinDate(dateArray)
        // formik.setFieldValue("preparation_date", dateArray)
    };

    const handleCheckoutDateChange = (date, dateArray) => {
        // formik.setFieldValue("expiry_date", dateArray)
        console.log("exp", dateArray)
        setcheckoutDate(dateArray)

    };

    return (
        <>

            <Modal
                isOpen={showRoomBookingModal}
                placement="top"

            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />


                            <ModalHeader className="flex flex-col gap-1 text-center text-large font-bold">ROOM : {selectedRoomToBook.title}</ModalHeader>
                            <ModalBody>
                                <form onSubmit={handleSubmit} >

                                    <div>


                                        <div className="w-full" >
                                            <p>Select check in date:</p>
                                            <DatePicker style={{ width: '100%', height: '60px' }} id="checkin_date" name="checkin_date" onChange={handleCheckinDateChange}  format={dateFormat} />
                                        </div>
                                        <div className="w-full" >
                                            <p>Enter check out date:</p>
                                            <DatePicker showNow style={{ width: '100%', height: '60px' }} id="checkout_date" name="checkout_date" onChange={handleCheckoutDateChange} format={dateFormat} />
                                        </div>


                                    </div>

                                    <div className='grid grid-cols-1 md:grid-cols-2 space-x-2'>


                                        {allGuests.map((field, index) => (
                                            <div className="input-container shadow-md" key={index} >
                                                <p className='text-xl font-bold mt-4 text-center'>Guest Details</p>
                                                <p className='text-xl font-bold mt-4 text-center'>Guest No. {index + 1} Details</p>

                                                <div className='grid grid-cols-2 w-full'>
                                                    <TextInput
                                                        type="text"
                                                        name="first_name"
                                                        placeholder="Enter first name"
                                                        value={field.first_name}
                                                        onChange={(event) =>
                                                            handleInputChange(index, event)
                                                        }
                                                    />

                                                    <TextInput
                                                        type="text"
                                                        name="last_name"
                                                        placeholder="Enter last name"
                                                        value={field.last_name}
                                                        onChange={(event) =>
                                                            handleInputChange(index, event)
                                                        }
                                                    />


                                                    <TextInput
                                                        type="text"
                                                        name="phone"
                                                        placeholder="Enter guest phone"
                                                        value={field.phone}
                                                        onChange={(event) =>
                                                            handleInputChange(index, event)
                                                        }
                                                    />
                                                    <Select variant='bordered' label="Select age type" className='bg-white mt-2' name='age_type' value={field.age_type} onChange={(event) =>
                                                        handleInputChange(index, event)

                                                    }

                                                    >
                                                        {ageTypes.map(option => (
                                                            <SelectItem key={option.value} value={option.value}>
                                                                {option.label}
                                                            </SelectItem>
                                                        ))}
                                                    </Select>
                                                    <Select variant='bordered' label="Select gender" className='bg-white mt-2' name='gender' value={field.gender} onChange={(event) =>
                                                        handleInputChange(index, event)

                                                    }

                                                    >
                                                        {genderTypes.map(option => (
                                                            <SelectItem key={option.value} value={option.value}>
                                                                {option.label}
                                                            </SelectItem>
                                                        ))}
                                                    </Select>
                                                    <Select variant='bordered' label="Select nationality" className='bg-white mt-2' name='nationality' value={field.gender} onChange={(event) =>
                                                        handleInputChange(index, event)

                                                    }

                                                    >
                                                        {countries.map(option => (
                                                            <SelectItem key={option.id} value={option.id}>
                                                                {option.title}
                                                            </SelectItem>
                                                        ))}
                                                    </Select>

                                                    <Select variant='bordered' label="Select identifier type" className='bg-white mt-2' name='identifier_type' value={field.identifier_type} onChange={(event) =>
                                                        handleInputChange(index, event)

                                                    }

                                                    >
                                                        {identifierTypes.map(option => (
                                                            <SelectItem key={option.value} value={option.value}>
                                                                {option.label}
                                                            </SelectItem>
                                                        ))}
                                                    </Select>


                                                    <TextInput
                                                        type="text"
                                                        name="identifier_number"
                                                        placeholder="Enter identifier number"
                                                        value={field.identifier_number}
                                                        onChange={(event) =>
                                                            handleInputChange(index, event)
                                                        }
                                                    />



                                                </div>




                                            </div>
                                        ))}

                                    </div>

                                    <Button type='submit' color='primary' className='max-w-md w-56 mt-4'>Save</Button>


                                </form>
                            </ModalBody>
                            <ModalFooter>
                                <Button color="danger" variant="flat" onPress={() => setshowRoomBookingModal(false)}>
                                    Cancel
                                </Button>


                            </ModalFooter>



                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
