import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Modal, ModalContent, ModalHeader, ModalBody, ModalFooter, Button, useDisclosure, Checkbox, Tabs, Tab, Input, Link, Card, CardBody, CardHeader, user } from "@heroui/react";
import { useFormik } from "formik";

import { ToastContainer, toast } from "react-toastify";
import { useStateContext } from "../../contexts/ContextProvider";



export default function RequiredDrinkQuantityFormModal({ openEditModal, setopenEditModal, quantity, setQuantity, selectedItem, currentSelectedItemQuantity }) {
    const [existing, setExisting] = useState()
    const { } = useStateContext()
    const [selectedItems, setselectedItems] = useState(localStorage.getItem("selectedItems") ? JSON.parse(localStorage.getItem("selectedItems")) : [])

    useEffect(() => {
        if (selectedItem && selectedItems.length)
            setExisting(selectedItems.length && selectedItems.find(x => x.id === selectedItem.id));
    }, [selectedItem, selectedItems])


    useEffect(() => {

        console.log("Existing....selected", selectedItem);

    }, [])

    const formik = useFormik({
        initialValues: {
            required_quantity: currentSelectedItemQuantity ? currentSelectedItemQuantity : "",

        },

        validationSchema: Yup.object({
            required_quantity: Yup.number()
                .min(0)
                .required().label('Quantity'),
        }),
        onSubmit: (values, { resetForm }) => {
            //Dispatch action
            setQuantity(values.required_quantity)
            setopenEditModal(false
            )

        },
    });


    useEffect(() => { console.log('errors', formik.errors) }, [])



    return (
        <>

            <Modal
                isOpen={openEditModal}
                placement="center"
            >
                <ModalContent>


                    {(onClose) => (
                        <>
                            <ToastContainer position="bottom-center" theme="colored" />


                            <ModalHeader className="flex flex-col gap-1 text-center text-large font-bold">{selectedItem.title}</ModalHeader>
                            <ModalBody>
                                <Card className="max-w-full ">

                                    <CardBody className="overflow-hidden">


                                        <form className="flex flex-col gap-4" onSubmit={formik.handleSubmit}>
                                            <Input
                                                id="required_quantity"
                                                name="required_quantity"
                                                autoFocus
                                                label="Required quantity"
                                                placeholder="Enter required quantity. Enter 0 to delete item"
                                                variant="bordered"
                                                type="text"
                                                onChange={formik.handleChange}
                                                onBlur={formik.handleBlur}
                                                defaultValue={formik.values.required_quantity}
                                                value={formik.values.required_quantity}
                                                color={formik.errors.required_quantity ? "danger" : "grey"}
                                                errorMessage={formik.errors.required_quantity}
                                            />
                                            <div className="flex gap-2 justify-end">
                                                <Button type="submit" fullWidth color="primary">
                                                    Save
                                                </Button>
                                            </div>
                                        </form>



                                    </CardBody>
                                </Card>
                            </ModalBody>
                            <ModalFooter>
                                <Button color="danger" variant="flat" onPress={() => setopenEditModal(false)}>
                                    Cancel
                                </Button>

                            </ModalFooter>



                        </>
                    )}
                </ModalContent>
            </Modal>
        </>
    );
}
